# Homebrew formula for the @REPO_OWNER@/homebrew-tap repository, generated by scripts/release.sh.
#   brew install @REPO_OWNER@/tap/terminal-mac
class TerminalMac < Formula
  desc "Separate virtual Mac for computer-use agents, viewed from the terminal"
  homepage "https://github.com/@REPO@"
  url "https://github.com/@REPO@/releases/download/@TAG@/@ARCHIVE@"
  version "@VERSION@-@BUILD@"
  sha256 "@SHA256@"
  license "MIT"

  depends_on arch: :arm64
  depends_on macos: :sonoma

  def install
    # The whole signed bundle: the CLI needs its entitlements and the bundled guest tools.
    prefix.install "TerminalMac.app"
    bin.install_symlink prefix/"TerminalMac.app/Contents/MacOS/terminal-mac"
  end

  def caveats
    <<~EOS
      Create and open your virtual Mac:  terminal-mac
      Claude Code tools:                  claude mcp add terminal-mac -- terminal-mac mcp
      Agent skill:                        terminal-mac skills install
      Other MCP clients:                  terminal-mac mcp --config
      VM data lives in ~/Library/Application Support/terminal-mac and survives upgrades.
    EOS
  end

  test do
    assert_match "terminal-mac @VERSION@", shell_output("#{bin}/terminal-mac --version")
    assert_match "name: terminal-mac", shell_output("#{bin}/terminal-mac skills get")
    ENV["TERMINAL_MAC_HOME"] = testpath/"data"
    system bin/"terminal-mac", "up", "--plan"
  end
end
